const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename that would be applied, in order.
 */
function migrate() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for .sql files only
  const sqlFiles = files.filter(file => {
    return file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile();
  });

  // If no SQL files found
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/ directory.');
    return;
  }

  // Sort files alphabetically to ensure consistent order
  // (Common naming convention: 001_initial.sql, 002_add_users.sql, etc.)
  sqlFiles.sort();

  // Log each migration file that would be applied
  console.log('Migrations that would be applied (in order):');
  console.log('===========================================');

  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('===========================================');
  console.log(`Total: ${sqlFiles.length} migration(s)`);
}

// Run the migration
if (require.main === module) {
  migrate();
}

module.exports = { migrate, MIGRATIONS_DIR };

