const { loadAllEnvVars } = require('./migrate.js');

// Temporarily override the audit URL to point to an unavailable service
process.argv.push('--audit-url=http://localhost:99999/api/audit');

// Reload the module with the new URL
delete require.cache[require.resolve('./migrate.js')];
const { sendAuditLog } = require('./migrate.js');

async function testAuditUnavailable() {
  console.log('Testing audit service when it is unavailable...\n');

  const envVars = loadAllEnvVars();
  console.log('Environment variables to be sent:');
  console.log(JSON.stringify(envVars, null, 2));
  console.log('\n' + '='.repeat(50) + '\n');

  // Temporarily change AUDIT_API_URL
  const http = require('http');
  const originalRequest = http.request;

  // Override to simulate connection refused
  http.request = function(options, callback) {
    const req = originalRequest.call(http, options, callback);
    // Simulate ECONNREFUSED error
    setImmediate(() => {
      req.emit('error', new Error('ECONNREFUSED'));
    });
    return req;
  };

  try {
    const result = await sendAuditLog(envVars);
    console.log('Audit log sent successfully!');
    console.log('Status:', result.statusCode);
  } catch (err) {
    console.error('✗ Audit failed:', err.message);
  }

  // Restore original
  http.request = originalRequest;
}

testAuditUnavailable();

