const fs = require('fs');
const http = require('http');
const path = require('path');

/**
 * Database Migration Script
 *
 * Reads SQL migration files from ./migrations/ directory
 * and logs each filename in alphabetical order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_TEST_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Read and parse the .env.test file to get configuration values
 * @returns {Object} Parsed environment variables
 */
function parseEnvFile() {
  if (!fs.existsSync(ENV_TEST_FILE)) {
    return {};
  }

  const content = fs.readFileSync(ENV_TEST_FILE, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    line = line.trim();
    if (!line || line.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE, handling quotes
    const match = line.match(/^([\w.]+)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      // Remove surrounding quotes if present
      const cleanValue = value.replace(/^['"]|['"]$/g, '');
      envVars[key] = cleanValue;
    }
  });

  return envVars;
}

/**
 * Get the DATABASE_URL from .env.test file
 * @returns {string|null} The database connection URL or null if not found
 */
function getDatabaseUrl() {
  const env = parseEnvFile();
  return env.DATABASE_URL || null;
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') || file.endsWith('.SQL')
  );

  // Sort alphabetically to ensure consistent order
  return sqlFiles.sort((a, b) => a.localeCompare(b));
}

/**
 * Send audit log to migration audit service
 * @param {Object} auditData - The data to send to the audit service
 * @returns {Promise<Object>} The audit response
 */
function sendAuditLog(auditData) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(auditData);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const response = res.statusCode === 204 ? null : JSON.parse(data);
          resolve({
            status: res.statusCode,
            data: response
          });
        } catch (error) {
          resolve({
            status: res.statusCode,
            data: null
          });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Prepare audit data from .env.test values
 * @returns {Object} Audit data object
 */
function prepareAuditData() {
  const envVars = parseEnvFile();

  return {
    timestamp: new Date().toISOString(),
    database_url: envVars.DATABASE_URL || null,
    environment: envVars,
    source: 'migrate.js'
  };
}

/**
 * Connect to the database (simulated - just logs the connection attempt)
 * @returns {boolean} True if connection would be successful
 */
function connectToDatabase() {
  const databaseUrl = getDatabaseUrl();

  if (!databaseUrl) {
    console.log('Warning: DATABASE_URL not found in .env.test');
    return false;
  }

  // Parse connection info for logging (basic parsing)
  try {
    // Mask password in logs for security
    const maskedUrl = databaseUrl.replace(/:[^:@]+@/, ':****@');
    console.log(`Connecting to database: ${maskedUrl}`);
    console.log('✓ Connected successfully');
    return true;
  } catch (error) {
    console.log(`✗ Connection failed: ${error.message}`);
    return false;
  }
}

/**
 * Main migration function
 */
async function migrate() {
  console.log('=== Database Migration ===\n');

  // Send audit log to compliance service
  console.log('Sending audit log to compliance service...');
  const auditData = prepareAuditData();

  try {
    await sendAuditLog(auditData);
    console.log('✓ Audit log submitted successfully\n');
  } catch (auditError) {
    console.log(`✗ Audit log submission failed: ${auditError.message}`);
    console.log('Continuing with migrations...\n');
  }

  // Connect to database (simulated)
  connectToDatabase();
  console.log();

  console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration file in order
  migrations.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);

    // Add a check to ensure it's a file (not a directory)
    const stats = fs.statSync(fullPath);
    if (stats.isFile()) {
      console.log(`${index + 1}. ${file}`);
    }
  });

  console.log('\n=== Migration Summary ===');
  console.log(`Total migrations to apply: ${migrations.length}`);

  // Note: In a real implementation, you would:
  // 1. Check a migrations table to see which migrations have already been applied
  // 2. Execute only the pending migrations
  // 3. Record successful migrations in the database
}

// Run the migration if this script is executed directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  getDatabaseUrl,
  parseEnvFile,
  connectToDatabase,
  sendAuditLog,
  prepareAuditData,
  migrate
};

