#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename that would be applied, in order.
 * 
 * Migration files should be named with a prefix that determines order,
 * such as: 001_initial_schema.sql, 002_add_users_table.sql, etc.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted list of migration filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only .sql files
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  if (sqlFiles.length === 0) {
    console.log(`No SQL migration files found in '${MIGRATIONS_DIR}'.`);
    return [];
  }

  // Sort files alphabetically (which works for numbered prefixes)
  const sortedFiles = sqlFiles.sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));

  return sortedFiles;
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration Script ===');
  console.log(`Scanning '${MIGRATIONS_DIR}' for SQL migration files...\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    return;
  }

  console.log(`Found ${migrations.length} migration file(s) to apply:\n`);

  // Log each migration file that would be applied
  migrations.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);

    console.log(`  [${index + 1}] ${file}`);
    console.log(`       Path: ${filePath}`);
    console.log(`       Size: ${stats.size} bytes`);
    console.log('');
  });

  console.log('=== Summary ===');
  console.log(`Total migrations to apply: ${migrations.length}`);
  console.log('(No changes were made - this is a dry run)');
}

// Run the migration script
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  migrate
};

