    console.log(`Audit data keys: ${Object.keys(payload).join(', ')}\n`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit log sent successfully (Status: ${res.statusCode})`);

          let responseObj;
          try {
            responseObj = JSON.parse(responseData);
          } catch (e) {
            responseObj = { message: responseData };
          }

          resolve({ statusCode: res.statusCode, data: responseObj });
        } else {
          console.error(`Audit service returned error status: ${res.statusCode}`);
          console.error(`Response: ${responseData}`);
          reject(new Error(`Audit service error: ${res.statusCode} - ${responseData}`));
        }
      });
