#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL migration files from the migrations directory and logs their filenames
 * in the order they would be applied (alphabetically sorted by filename).
 */
function runMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for SQL files only
  const sqlFiles = files.filter(file => {
    const ext = path.extname(file).toLowerCase();
    return ext === '.sql';
  });

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  // Sort files alphabetically to ensure consistent order
  sqlFiles.sort();

  // Log each file that would be applied
  console.log(`Found ${sqlFiles.length} migration file(s) to apply:\n`);

  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Run the migration script
runMigrations();

