const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }

  // Filter for SQL files (case-insensitive)
  const sqlFiles = files.filter(file => 
    file.toLowerCase().endsWith('.sql')
  );

  // Sort files alphabetically to ensure consistent order
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  return sqlFiles;
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration Script ===\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log(`No SQL migration files found in '${MIGRATIONS_DIR}'.`);
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file that would be applied
  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);

    // Get file stats for additional info
    const stats = fs.statSync(filePath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
  });

  console.log('\n=== Migration Summary ===');
  console.log(`Total migrations to apply: ${migrationFiles.length}`);
  console.log('(Note: This script only logs migrations; no database changes are applied)');
}

// Run the migration if this script is executed directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  migrate
};

