const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Parse a .env file and return key-value pairs as an object
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Parsed environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const env = {};
  const content = fs.readFileSync(filePath, 'utf-8');

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }
    // Parse KEY=VALUE pairs
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      env[key.trim()] = value.trim();
    }
  });

  return env;
}

/**
 * Get the DATABASE_URL from .env.test file
 * Falls back to process.env.DATABASE_URL if .env.test doesn't exist
 * @returns {string|null} Database URL or null if not found
 */
function getDatabaseUrl() {
  // First try reading from .env.test file
  const envVars = parseEnvFile(ENV_FILE);

  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  // Fall back to process.env
  return process.env.DATABASE_URL || null;
}

/**
 * Simulate database connection and log success message
 * @param {string} dbUrl - Database connection URL
 */
function connectToDatabase(dbUrl) {
  if (!dbUrl) {
    console.error('Error: DATABASE_URL not found in .env.test or process.env');
    process.exit(1);
  }

  // Log connection message (simulated - no actual connection)
  const connectionInfo = getConnectionInfo(dbUrl);
  console.log(`✓ Successfully connected to database ${connectionInfo} from ${ENV_FILE}`);
}

/**
 * Extract sanitized connection info from database URL
 * @param {string} dbUrl - Database connection URL
 * @returns {string} Sanitized connection info (host:port/database)
 */
function getConnectionInfo(dbUrl) {
  try {
    // Parse standard connection URLs like:
    // postgresql://user:pass@localhost:5432/dbname
    // mysql://user:pass@localhost:3306/dbname
    const match = dbUrl.match(/^[^:]+:\/\/[^@]+@([^:/]+)(?::(\d+))?\/([^?]+)/);
    if (match) {
      const [, host, port, database] = match;
      return `${host}${port ? ':' + port : ''}/${database}`;
    }
    // If we can't parse it, just show that it's connected
    return '(connection established)';
  } catch (error) {
    return '(connection established)';
  }
}

