/**
 * Parses a .env file and returns key-value pairs
 */
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    // Skip empty lines and comments
    if (!line || line.startsWith('#')) return;

    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();
      // Remove quotes if present
      value = value.replace(/^["']|["']$/g, '');
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Reads DATABASE_URL from .env.test file
 */
function getDatabaseUrl(envVars = null) {
  // If env vars not provided, read and parse the file
  if (!envVars) {
    if (!fs.existsSync(ENV_FILE)) {
      console.log(`Environment file '${ENV_FILE}' not found.`);
      return null;
    }
    envVars = parseEnvFile(ENV_FILE);
  }

  return envVars.DATABASE_URL || null;
}

