#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in alphabetical order.
 */

const MIGRATIONS_DIR = './migrations';

/**
 * Check if migrations directory exists
 */
function checkMigrationsDir() {
  const fullPath = path.resolve(MIGRATIONS_DIR);
  if (!fs.existsSync(fullPath)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }
  return fullPath;
}

/**
 * Get all SQL files from the migrations directory
 * @param {string} dirPath - Path to migrations directory
 * @returns {Array<string>} - Array of SQL filenames
 */
function getMigrationFiles(dirPath) {
  try {
    const files = fs.readdirSync(dirPath);
    // Filter for .sql files only
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort(); // Sort alphabetically to ensure consistent order

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log each migration file that would be applied
 * @param {Array<string>} files - Array of migration filenames
 */
function logMigrationFiles(files) {
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log(`\nTotal: ${files.length} migration(s)`);
}

/**
 * Main migration function
 */
function migrate() {
  console.log('Migration Script');
  console.log('================\n');

  const dirPath = checkMigrationsDir();
  const migrationFiles = getMigrationFiles(dirPath);

  logMigrationFiles(migrationFiles);

  // Note: This script only logs what migrations would be applied.
  // To actually apply migrations, you would need to:
  // 1. Connect to a database
  // 2. Execute each SQL file's contents
  // 3. Track which migrations have been applied (e.g., in a migrations table)
}

// Run migration if this script is executed directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  checkMigrationsDir,
  getMigrationFiles,
  logMigrationFiles,
  migrate
};

