#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in alphabetical order.
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Read and parse the .env.test file to get DATABASE_URL
 * @returns {string|null} - Database connection URL or null if not found
 */
function resolveConnectionString() {
  const envPath = path.resolve(ENV_FILE);

  if (!fs.existsSync(envPath)) {
    console.error(`Error: Environment file '${ENV_FILE}' does not exist.`);
    process.exit(1);
  }

  try {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }
      // Parse DATABASE_URL variable
      const match = trimmedLine.match(/^DATABASE_URL\s*=\s*(.+)$/);
      if (match) {
        let value = match[1].trim();
        // Remove quotes if present (single or double)
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        return value;
      }
    }

    console.error(`Error: DATABASE_URL not found in '${ENV_FILE}'.`);
    process.exit(1);
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Simulates connecting to the database and logs success
 * @param {string} connectionString - The database connection string
 */
