const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
function runMigrations() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('Migrations directory not found:', migrationsDir);
    return;
  }

  // Read all files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    return;
  }

  // Filter for SQL files and sort them alphabetically
  // This assumes filenames are named in a way that alphabetical order
  // equals the desired execution order (e.g., 001_init.sql, 002_users.sql)
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in', migrationsDir);
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  // Log each filename in order
  sqlFiles.forEach((file, index) => {
    const fullPath = path.join(migrationsDir, file);
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\nMigration plan complete. No files were actually executed.');
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations };

