const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files sorted by filename
 * @returns {Array} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (case insensitive)
    const sqlFiles = files.filter(file => 
      file.toLowerCase().endsWith('.sql')
    );

    // Sort filenames alphabetically to ensure consistent order
    sqlFiles.sort((a, b) => a.localeCompare(b));

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log migration files that would be applied
 */
function logMigrations() {
  console.log('=== Database Migration Script ===\n');
  console.log(`Scanning '${MIGRATIONS_DIR}' for migration files...\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((filename, index) => {
    console.log(`  ${index + 1}. ${filename}`);
  });

  console.log('\n=== Migration Summary ===');
  console.log(`Total migrations to apply: ${migrations.length}`);
  console.log('(Note: This script only logs migrations - no SQL is executed)');
}

/**
 * Read and display contents of a specific migration file
 * @param {string} filename - The migration filename
 */
function previewMigration(filename) {
  const filePath = path.join(MIGRATIONS_DIR, filename);

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    console.log(`\n--- Contents of ${filename} ---`);
    console.log(content);
    console.log('--- End of file ---\n');
  } catch (error) {
    console.error(`Error reading migration file '${filename}': ${error.message}`);
  }
}

// Run the migration logging
if (require.main === module) {
  logMigrations();

  // Optional: If a specific filename is passed as argument, preview it
  const args = process.argv.slice(2);
  if (args.length > 0) {
    const filename = args[0];
    if (filename.endsWith('.sql')) {
      previewMigration(filename);
    }
  }
}

// Export functions for testing or use in other modules
module.exports = {
  getMigrationFiles,
  logMigrations,
  previewMigration
};

