const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load and parse .env.test file
 * @returns {Object} Parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.log(`Warning: '${ENV_FILE}' not found.`);
      return {};
    }

    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE, handling quoted values
      const match = trimmed.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes from value
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

/**
 * Get the database connection string from environment
 * @returns {string|null} Database URL or null if not found
 */
function getDatabaseUrl() {
  // First check .env.test file
  const envVars = loadEnvFile();

  // Return DATABASE_URL from file
  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  // Fall back to process environment
  return process.env.DATABASE_URL || null;
}

/**
 * Log connection status
 */
function logConnectionStatus() {
  const dbUrl = getDatabaseUrl();

  if (!dbUrl) {
    console.log('\n=== Database Connection ===');
    console.log('Warning: DATABASE_URL not found in .env.test or environment.');
    return false;
  }

  console.log('\n=== Database Connection ===');
  console.log('Connected successfully!');

  // Log connection info (mask password for security)
  const maskedUrl = maskDatabaseUrl(dbUrl);
  console.log(`Using: ${maskedUrl}`);

  return true;
}

/**
 * Mask sensitive parts of database URL for logging
 * @param {string} url - The database URL
 * @returns {string} URL with password masked
 */
function maskDatabaseUrl(url) {
  try {
    // Match postgres://user:password@host:port/db or similar patterns
    const masked = url.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@');
    return masked;
  } catch (error) {
    // If parsing fails, just return a generic message
    return '[URL]';
  }
}

