    const sqlFiles = files.filter(file => {
      return path.extname(file).toLowerCase() === '.sql';
    });

    // Sort files alphanumerically to ensure consistent order
    sqlFiles.sort((a, b) => a.localeCompare(b, 'en', { numeric: true, sensitivity: 'base' }));

