async function sendToAuditService(auditData) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_ENDPOINT);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit service: Logged successfully (${res.statusCode})`);
          resolve();
        } else {
          console.warn(`Audit service: Unexpected response (${res.statusCode})`);
          // Don't fail migrations if audit service is unavailable
          resolve();
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`Audit service: Connection failed - ${error.message}`);
      // Don't fail migrations if audit service is unavailable
      resolve();
    });

    req.write(JSON.stringify(auditData));
    req.end();
  });
}

