const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Read and sort migration files from the migrations directory
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only .sql files
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in the migrations directory.');
    return [];
  }

  // Sort files alphabetically (typically迁移文件 are named with timestamps or versions)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Log each migration file that would be applied
 */
function logMigrationsToApply() {
  console.log('=== Migration Script ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);
  console.log('Migrations to apply (in order):');
  console.log('----------------------------------------');

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);

    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${filePath}`);
    console.log(`   Size: ${stats.size} bytes`);

    // Optionally read and display a preview of the SQL
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    const lineCount = sqlContent.split('\n').length;
    console.log(`   Lines: ${lineCount}`);
    console.log('');
  });

  console.log('----------------------------------------');
  console.log(`\nTotal: ${migrationFiles.length} migration(s) would be applied.`);
}

/**
 * Main execution
 */
function main() {
  try {
    logMigrationsToApply();
  } catch (error) {
    console.error('Error running migration script:', error.message);
    process.exit(1);
  }
}

// Run the script if executed directly
if (require.main === module) {
  main();
}

module.exports = { getMigrationFiles, logMigrationsToApply };

